"""HQ ACL helpers for ПСС multi-dispatcher roles."""

from __future__ import annotations

from functools import wraps

from flask import jsonify
from flask_babel import gettext
from flask_security import current_user

# Flask-Security role names (also created in DB on ensure_hq_roles)
ROLE_ADMIN = "psr_admin"
ROLE_COMMANDER = "psr_commander"
ROLE_DISPATCHER = "psr_dispatcher"
ROLE_OBSERVER = "psr_observer"

HQ_ROLES = (ROLE_ADMIN, ROLE_COMMANDER, ROLE_DISPATCHER, ROLE_OBSERVER)
WRITE_ROLES = ("administrator", ROLE_ADMIN, ROLE_COMMANDER, ROLE_DISPATCHER)
INVITE_ROLES = ("administrator", ROLE_ADMIN)
CRM_WRITE_ROLES = ("administrator", ROLE_ADMIN, ROLE_COMMANDER, ROLE_DISPATCHER)
CRM_COMMAND_ROLES = ("administrator", ROLE_ADMIN, ROLE_COMMANDER)
CRM_READ_ROLES = ("administrator", ROLE_ADMIN, ROLE_COMMANDER, ROLE_DISPATCHER, ROLE_OBSERVER)
REPORT_ROLES = ("administrator", ROLE_ADMIN, ROLE_COMMANDER)

_roles_ready = False


def _role_names(user=None) -> set[str]:
    u = user or current_user
    if not u or not getattr(u, "is_authenticated", False):
        return set()
    return {r.name for r in (u.roles or [])}


def has_any_role(*names: str, user=None) -> bool:
    roles = _role_names(user)
    return bool(roles.intersection(names))


def is_hq_user(user=None) -> bool:
    return has_any_role(*HQ_ROLES, "administrator", user=user)


def can_hq_write(user=None) -> bool:
    """Observer is read-only; field/legacy users without HQ roles keep write."""
    roles = _role_names(user)
    if ROLE_OBSERVER in roles and not roles.intersection(WRITE_ROLES):
        return False
    return True


def can_crm_read(user=None) -> bool:
    return has_any_role(*CRM_READ_ROLES, user=user)


def can_crm_write(user=None) -> bool:
    return has_any_role(*CRM_WRITE_ROLES, user=user)


def can_crm_command(user=None) -> bool:
    return has_any_role(*CRM_COMMAND_ROLES, user=user)


def can_invite(user=None) -> bool:
    return has_any_role(*INVITE_ROLES, user=user)


def can_reports(user=None) -> bool:
    return has_any_role(*REPORT_ROLES, user=user)


def ensure_hq_roles(app=None) -> None:
    """Idempotent: create HQ roles in Flask-Security datastore."""
    global _roles_ready
    if _roles_ready:
        return
    from flask import current_app
    from opentakserver.extensions import db

    flask_app = app or current_app
    ds = flask_app.security.datastore
    specs = (
        (ROLE_ADMIN, {"psr-admin", "administrator"}),
        (ROLE_COMMANDER, {"psr-commander", "user-read", "user-write"}),
        (ROLE_DISPATCHER, {"psr-dispatcher", "user-read", "user-write"}),
        (ROLE_OBSERVER, {"psr-observer", "user-read"}),
    )
    try:
        for name, perms in specs:
            ds.find_or_create_role(name=name, permissions=perms)
        db.session.commit()
        _roles_ready = True
    except Exception:
        db.session.rollback()
        raise


def forbid(msg: str = "Forbidden", code: int = 403):
    return jsonify({"success": False, "error": gettext(msg)}), code


def require_roles(*role_names: str):
    """Decorator: authenticated user must have one of the roles."""

    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            ensure_hq_roles()
            if not current_user or not current_user.is_authenticated:
                return forbid("Authentication required", 401)
            if not has_any_role(*role_names):
                return forbid("Insufficient role")
            return fn(*args, **kwargs)

        return wrapper

    return decorator


def deny_observer_write_response():
    """Return 403 response if current user is observer-only; else None."""
    if not can_hq_write():
        return forbid("Observer role is read-only")
    return None
